int find_sub(char x[],char y[],int s,int l)//finds substring and returns starting index if found else returns -1
{
    int i,j,c=0;
    for(i=s;i<100-s;i++)
    {
        if(x[i]==y[0])
        {
           c=i;
           for(j=1;j<l;j++)
           {

                if(x[++i]!=y[j])
            {
             break; 
            }
            if(j==l-1)
            return c;
           }
        }
    } 
    return -1;
}
void rev_sub(char s[],int a,int b)
{
   char dup[100];
   int i,c=0;
   for(i=b;i>=a;i--)
   dup[c++]=s[i];
   c++;
   c=0;
   for(i=a;i<=b;i++)
   s[i]=dup[c++];

}

